// - Search and salary filters must work together.
// - Add a Reset Filters button.
// - Display "No employees found" when there are no matches.
// - Preserve the original employee data.

// ===========================================
//          Code After Solved Bugs
// ===========================================
import { useState } from "react";
function Task8() {
  const [employees] = useState([
    { id: 1, name: "Rahul", salary: 25000 },
    { id: 2, name: "Priya", salary: 45000 },
    { id: 3, name: "Arjun", salary: 30000 },
    { id: 4, name: "Sneha", salary: 55000 }
  ]);

  const [search, setSearch] = useState("");
  const [minimumSalary, setMinimumSalary] = useState('');

//  ============================
//     Search Employees Logic
// ============================

  const filteredEmployees = employees.filter((employee) => {
    return employee.name.toLowerCase().includes(search.toLowerCase()) &&
    employee.salary >= minimumSalary;
  });

//  ============================
//     Reset Logic
// ============================

  function handleReset(){
    setMinimumSalary("")
    setSearch("")
  }

//  ================================
//     Display all employees Logic
// ================================

  return (
    <div>
      <h2>Employee Management</h2>
      <input
        value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Search employee"
      />
      <input
        type="text"
        value={minimumSalary} onChange={(e) => setMinimumSalary(Number(e.target.value))}
      />

      <button onClick={handleReset}>Reset</button>

      {filteredEmployees.length>0 ? filteredEmployees.map((employee) => (
        <p key={employee.id}>
          {employee.name} - ₹{employee.salary}
        </p>
      )):<h5>No Employees Found</h5>}
    </div>
  );
}

export default Task8;